def filter_product_by_features(key: str, value: Optional[str] = None, category: Optional[str] = None, max_pages: int = 5, fields: Optional[list[str]] = None) -> dict:
    """Find products whose features contain a matching entry; candidate pages are fetched and filtered in memory and the scan coverage is reported.

    Scans up to max_pages pages in memory and reports coverage (pages_scanned, truncated). A truncated scan means more candidates exist than were checked.

    Args:
        key: Key to look for in features (matches feature_code).
        value: Optional value the entry must also have (matches feature_value or unit).
        category: Filter by product group
        max_pages: Candidate pages to scan, 1 to 10. The tool fetches the pages itself.
        fields: Optional list of field names to return (at most 12; unknown names are ignored).
    """
    try:
        max_pages = _clamp(max_pages, 1, 10)
        needle = str(key).strip()
        if not needle or len(needle) > 256:
            return _err("invalid_argument", "A key of 1 to 256 characters is required.")
        if value is not None and len(str(value)) > 256:
            return _err("invalid_argument", "value is too long (at most 256 characters).")
        if category is not None and len(str(category)) > 256:
            return _err("invalid_argument", "category is too long (at most 256 characters).")
        sel = _select_fields(fields, _ALLOWED["product"], _DEFAULT["product"])
        base_query = {}
        if category is not None:
            base_query["category"] = _qv(category)
        matches = []
        scanned = 0
        truncated = False
        for page in range(1, max_pages + 1):
            query = dict(base_query)
            query["page"] = page
            query["size"] = 50
            rows = _rows(_http_json("/products", query))
            scanned += 1
            for row in rows:
                hits = _nested_hits(row.get("features"), ["feature_code"], ["feature_value", "unit"], needle, value)
                if hits:
                    item = _project(row, sel)
                    item["features"] = hits
                    matches.append(item)
                    if len(matches) >= MAX_RESPONSE_ITEMS:
                        truncated = True
                        break
            if truncated:
                break
            if len(rows) < 50:
                break
            if page * 50 >= 10000:
                truncated = True
                break
        else:
            truncated = True
        coverage = {"pages_scanned": scanned, "truncated": truncated, "note": "The scan stopped before every candidate page was checked; matching items may be missing. Narrow the request or raise max_pages." if truncated else "Every candidate page was checked."}
        out = {"ok": True, "results": matches, "count": len(matches), "coverage": coverage}
        if not matches:
            out["message"] = "No matches found among the scanned candidates." + (" The scan was incomplete, so a match may exist further on." if truncated else "")
        elif truncated:
            out["message"] = "Results may be incomplete: the scan stopped before every page was checked."
        return out
    except _Fail as exc:
        return _fail(exc)
    except Exception:
        return _err("internal", _INTERNAL_MESSAGE)


def list_products(page: int = 1, page_size: int = 20, category: Optional[str] = None, fields: Optional[list[str]] = None) -> dict:
    """List products, one page at a time. Source note: List products one page at a time

    page_size is clamped to the range 1 to 50; larger values are reduced, not rejected.

    Results beyond position 10000 are not available; a warning with advice is returned instead.

    Args:
        page: Page number, starting at 1.
        page_size: Rows per page (1 to 50).
        category: Filter by product group
        fields: Optional list of field names to return (at most 12; unknown names are ignored).
    """
    try:
        page = _clamp(page, 1, 1000000)
        page_size = _clamp(page_size, 1, 50)
        if page * page_size > 10000:
            return {"ok": True, "results": [], "count": 0, "warning": "Result ceiling reached: results beyond position 10000 are not available. Narrow the request with the category filter instead of paging deeper.", "page": page, "page_size": page_size}
        if category is not None and len(str(category)) > 256:
            return _err("invalid_argument", "category is too long (at most 256 characters).")
        sel = _select_fields(fields, _ALLOWED["product"], _DEFAULT["product"])
        query = {}
        query["page"] = page
        query["size"] = page_size
        if category is not None:
            query["category"] = _qv(category)
        data = _http_json("/products", query)
        rows = _rows(data)[: min(page_size, MAX_RESPONSE_ITEMS)]
        if not rows:
            return _no_results("product", "Try fewer filters or a broader search term.")
        results = [_project(row, sel) for row in rows]
        return {"ok": True, "results": results, "count": len(results), "page": page, "page_size": page_size}
    except _Fail as exc:
        return _fail(exc)
    except Exception:
        return _err("internal", _INTERNAL_MESSAGE)


def lookup_product_by_id(product_id: str, fields: Optional[list[str]] = None) -> dict:
    """Look up one product by id. Says clearly when it does not exist. Source note: Fetch one product by code

    Args:
        product_id: Product code
        fields: Optional list of field names to return (at most 12; unknown names are ignored).
    """
    try:
        if len(str(product_id)) > 256:
            return _err("invalid_argument", "product_id is too long (at most 256 characters).")
        sel = _select_fields(fields, _ALLOWED["product"], _DEFAULT["product"])
        query = {}
        data = _http_json("/products/" + _seg(product_id), query or None)
        item = _item(data)
        if not item:
            return _not_found("product", product_id)
        return {"ok": True, "result": _project(item, sel)}
    except _Fail as exc:
        if exc.kind == "not_found":
            return _not_found("product", product_id)
        return _fail(exc)
    except Exception:
        return _err("internal", _INTERNAL_MESSAGE)


def search_product(q: str, page: int = 1, page_size: int = 20, fields: Optional[list[str]] = None) -> dict:
    """Search products by free text, one page at a time. Source note: Search products by free text. See for details

    page_size is clamped to the range 1 to 50; larger values are reduced, not rejected.

    Results beyond position 10000 are not available; a warning with advice is returned instead.

    Args:
        q: Free text query
        page: Page number, starting at 1.
        page_size: Rows per page (1 to 50).
        fields: Optional list of field names to return (at most 12; unknown names are ignored).
    """
    try:
        page = _clamp(page, 1, 1000000)
        page_size = _clamp(page_size, 1, 50)
        if page * page_size > 10000:
            return {"ok": True, "results": [], "count": 0, "warning": "Result ceiling reached: results beyond position 10000 are not available. Narrow the request with a more specific search term instead of paging deeper.", "page": page, "page_size": page_size}
        if len(str(q)) > 256:
            return _err("invalid_argument", "q is too long (at most 256 characters).")
        sel = _select_fields(fields, _ALLOWED["product"], _DEFAULT["product"])
        query = {}
        query["page"] = page
        query["size"] = page_size
        query["q"] = _qv(q)
        data = _http_json("/products/search", query)
        rows = _rows(data)[: min(page_size, MAX_RESPONSE_ITEMS)]
        if not rows:
            return _no_results("product", "Try fewer filters or a broader search term.")
        results = [_project(row, sel) for row in rows]
        return {"ok": True, "results": results, "count": len(results), "page": page, "page_size": page_size}
    except _Fail as exc:
        return _fail(exc)
    except Exception:
        return _err("internal", _INTERNAL_MESSAGE)


